    make(3, "矩形甲的長、寬為 4 公分與 6 公分，矩形乙的長、寬為 6 公分與 9 公分。兩矩形的相似比（甲：乙）為何？", {"A": "1：1", "B": "2：3", "C": "3：2", "D": "4：9"}, "B", "對應長邊 4：6＝2：3，短邊 6：9＝2：3，比例一致，所以相似比為 2：3，選 B。", "比較兩組對應邊，確認比例方向與兩邊一致。", ["配對甲長 4 與乙長 6。", "化簡 4：6＝2：3。", "配對甲寬 6 與乙寬 9。", "化簡 6：9＝2：3，兩比例一致。", "選 B。"], "medium"),
    make(4, "兩個相似多邊形的周長比（小：大）為 3：5。若小多邊形周長為 24 公分，大多邊形周長是多少？", {"A": "32 公分", "B": "36 公分", "C": "40 公分", "D": "45 公分"}, "C", "相似圖形的周長比等於對應邊的相似比，24：P＝3：5，所以 P＝24×5÷3＝40 公分，選 C。", "周長是長度量，依相似比一次放大，不使用面積平方比。", ["寫出小：大周長比 3：5。", "列式 24：P＝3：5。", "交叉相乘得 3P＝120。", "解得 P＝40 公分。", "選 C，周長比仍是一次方比例。"], "medium"),
    make(5, "兩個相似圖形的相似比（小：大）為 1：2，則它們的面積比（小：大）為何？", {"A": "1：2", "B": "1：3", "C": "1：4", "D": "2：4"}, "C", "面積比等於相似比的平方，1²：2²＝1：4，選 C。", "辨認題目問面積，將長度相似比平方。", ["讀出長度相似比小：大＝1：2。", "面積與長度平方成比例。", "分別平方 1² 與 2²。", "得到面積比 1：4。", "選 C，不可直接使用 1：2。"], "medium"),
    make(6, "相似三角形 ABC 與 DEF 中，AB：DE＝2：3。若 BC＝10 公分，對應的 EF 長多少？", {"A": "12 公分", "B": "15 公分", "C": "18 公分", "D": "20 公分"}, "B", "BC 對應 EF，BC：EF＝2：3，因此 10：EF＝2：3，EF＝15 公分，選 B。", "先依頂點順序找對應邊，再套相似比。", ["由 ABC～DEF 配對 AB↔DE、BC↔EF。", "寫出 BC：EF＝2：3。", "列式 10：EF＝2：3。", "計算 EF＝10×3÷2＝15。", "選 B。"], "easy"),
    make(7, "相似三角形中，小三角形的高為 5 公分、大三角形的高為 8 公分。若小三角形一邊為 10 公分，對應的大邊為多少？", {"A": "12.5 公分", "B": "13 公分", "C": "16 公分", "D": "18 公分"}, "C", "相似比小：大＝5：8，所以 10：x＝5：8，x＝10×8÷5＝16 公分，選 C。", "用對應高求出相似比，再同步放大對應邊。", ["由高度得到小：大＝5：8。", "將邊長列成 10：x＝5：8。", "交叉相乘得 5x＝80。", "解得 x＝16 公分。", "選 C。"], "medium"),
