    make(9, "三角形甲的三邊為 3、4、5；三角形乙的三邊為 6、8、11。兩三角形是否相似？", {"A": "是，相似比 1：2", "B": "是，相似比 2：1", "C": "否，對應邊比例不一致", "D": "無法由邊長判斷"}, "C", "前兩組若放大 2 倍為 6、8，但 5 應對應 10 而非 11，三邊比例不一致，所以不相似，選 C。", "將邊由小到大配對，檢查每一組比例是否相同。", ["配對 3↔6，比例為 1：2。", "配對 4↔8，比例也為 1：2。", "配對 5 應對應 10，但乙為 11。", "三組比例不一致。", "選 C。"], "medium"),
    make(10, "兩個相似矩形的長度相似比（小：大）為 2：3。小矩形面積為 40 平方公分，大矩形面積是多少？", {"A": "60", "B": "80", "C": "90", "D": "120"}, "C", "面積比為 2²：3²＝4：9，因此 40：A＝4：9，A＝40×9÷4＝90 平方公分，選 C。", "先把長度比平方成面積比，再用比例求面積。", ["讀出長度比小：大＝2：3。", "平方得到面積比 4：9。", "列式 40：A＝4：9。", "計算 A＝40×9÷4＝90。", "選 C，面積單位為平方公分。"], "hard"),
